import{_ as o,C as l,o as a,c as n,a5 as e,E as s}from"./chunks/framework.Bkm3ODFN.js";const h=JSON.parse('{"title":"🏭 Modbus 工业点位采集与字节序","description":"","frontmatter":{},"headers":[],"relativePath":"iot/modbus.md","filePath":"iot/modbus.md","lastUpdated":1794271174000}'),i={name:"iot/modbus.md"};function r(c,t,g,u,_,b){const d=l("ModbusEndianCalculator");return a(),n("div",null,[t[0]||(t[0]=e('<h1 id="🏭-modbus-工业点位采集与字节序" tabindex="-1">🏭 Modbus 工业点位采集与字节序 <a class="header-anchor" href="#🏭-modbus-工业点位采集与字节序" aria-label="Permalink to &quot;🏭 Modbus 工业点位采集与字节序&quot;">​</a></h1><p>Modbus 是工业现场应用最广泛的通信协议之一。MzMedia 提供了高度可视化的 Modbus 点位采集配置器。</p><hr><h2 id="_1-核心采集参数解析" tabindex="-1">1. 核心采集参数解析 <a class="header-anchor" href="#_1-核心采集参数解析" aria-label="Permalink to &quot;1. 核心采集参数解析&quot;">​</a></h2><p>在 <strong>设备管理 -&gt; Modbus 配置</strong> 中，每个从站设备可配置以下参数：</p><ul><li><strong>从站地址 (Slave ID)</strong>：<code>1 ~ 247</code>，区分同一总线上的不同仪器仪表；</li><li><strong>轮询周期 (Poll Interval)</strong>：单位毫秒，支持从 100ms（高频工况）到数小时自由调节；</li><li><strong>功能码 (Function Code)</strong>： <ul><li><code>01 Read Coils</code> (读线圈，布尔量开关状态)</li><li><code>02 Read Discrete Inputs</code> (读离散输入，传感器开关量)</li><li><code>03 Read Holding Registers</code> (读保持寄存器，模拟量读写)</li><li><code>04 Read Input Registers</code> (读输入寄存器，模拟量只读)</li></ul></li><li><strong>寄存器起始地址 (Address)</strong>：PLC 或仪表手册标注的寄存器起始偏移量（需注意 0-based 还是 1-based）；</li><li><strong>缩放系数 (Scale Factor)</strong>：例如传感器采集电压乘以 <code>0.1</code> 得到实际伏特数；</li><li><strong>数据类型</strong>：<code>int16</code>, <code>uint16</code>, <code>int32</code>, <code>uint32</code>, <code>float32</code>, <code>double64</code>, <code>bool</code>。</li></ul><hr><h2 id="endian-calc" tabindex="-1">2. 在线字节序转换与 CRC16 计算器 <a class="header-anchor" href="#endian-calc" aria-label="Permalink to &quot;2. 在线字节序转换与 CRC16 计算器 {#endian-calc}&quot;">​</a></h2><p>当现场仪表上传的浮点数出现异常（例如读取温度出现 <code>1.23e-38</code> 或超大负数），可通过本工具在线粘贴 4 字节 Hex 原始报文，直接对照四种模式的解析值与 CRC 校验：</p>',9)),s(d),t[1]||(t[1]=e('<hr><h2 id="_3-工业字节序-endianness-调优指南" tabindex="-1">3. 工业字节序 (Endianness) 调优指南 <a class="header-anchor" href="#_3-工业字节序-endianness-调优指南" aria-label="Permalink to &quot;3. 工业字节序 (Endianness) 调优指南&quot;">​</a></h2><p>不同厂商的 PLC（西门子、施耐德、三菱、欧姆龙）对于 32 位及以上数据类型的存储字节顺序存在差异，MzMedia 内置了全套排列组合支持：</p><table tabindex="0"><thead><tr><th style="text-align:left;">字节序名称</th><th style="text-align:left;">排列模式</th><th style="text-align:left;">典型代表厂商</th><th style="text-align:left;">说明</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Big-Endian (ABCD)</strong></td><td style="text-align:left;">高字节在前，高字在前</td><td style="text-align:left;">西门子 S7-1200/1500、标准 Modbus</td><td style="text-align:left;">最常规的大端模式</td></tr><tr><td style="text-align:left;"><strong>Little-Endian (DCBA)</strong></td><td style="text-align:left;">低字节在前，低字在前</td><td style="text-align:left;">PC x86 工控机</td><td style="text-align:left;">纯粹的小端模式</td></tr><tr><td style="text-align:left;"><strong>Big-Endian Byte Swap (BADC)</strong></td><td style="text-align:left;">字节交换</td><td style="text-align:left;">部分国产数显仪、流量计</td><td style="text-align:left;">单字内部高低字节调换</td></tr><tr><td style="text-align:left;"><strong>Little-Endian Byte Swap (CDAB)</strong></td><td style="text-align:left;">字交换（中端模式）</td><td style="text-align:left;">施耐德、Modicon PLC</td><td style="text-align:left;">两个 16 位字的高低位置调换</td></tr></tbody></table><blockquote><p><strong>提示</strong>：如果在平台中读取到的浮点数出现极大异常值，通常是因为选择了错误的字节序，只需在点位管理中切换为 <code>CDAB</code> 或 <code>BADC</code> 即可即时纠正。</p></blockquote>',5))])}const x=o(i,[["render",r]]);export{h as __pageData,x as default};
